CHAPTER_META = {'chapter_num': 8, 'title': 'Clothes - How Things are Made', 'class_level': 'Class 5', 'subject': 'Science (Curiosity, NEP 2020)', 'description': 'NCERT Class 5 Science Chapter 8: Clothes - How Things are Made interactive animated laboratory.'}

SLIDES = [{'id': 1, 'title': "Nature's Weavers", 'subtitle': 'The Baya Weaverbird: Master Architects of Hanging Woven Pouch Nests', 'concept_html': '\n            <p>Long before human beings invented spinning wheels or automated looms, animals and birds were already the planet\'s master textile engineers. Foremost among them is the extraordinary <strong>male baya weaver (weaverbird)</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🌾 Harvesting Fibre Strands</span>\n                    <p class="text-xs text-slate-300">\n                        During the monsoon breeding season, the male baya weaver uses its strong, sharp conical beak to snip long, flexible blades of tough grass, palm fronds, and paddy leaves, stripping them into uniform ribbons.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🪹 Over-and-Under Interlacing</span>\n                    <p class="text-xs text-slate-300">\n                        Perched on an acacia or thorny palm branch hanging over water (to deter snakes), the bird ties complex knots and interlaces hundreds of grass strips <strong>over and under each other</strong>. It weaves a waterproof, wind-resistant pouch with a central nesting chamber and a downward-hanging tubular entrance tunnel!\n                    </p>\n                </div>\n            </div>\n            <p>Female baya weavers inspect multiple woven nests across the colony, choosing a mate based on the tightness, security, and craftsmanship of the weaving!</p>\n        ', 'spoken_text': 'Welcome young scientists to Chapter 8: Clothes, How Things are Made! Before humans ever held a needle or operated a loom, nature had already invented the art of weaving. High on thorny acacia trees swaying in the monsoon wind, look at the male baya weaverbird! With its conical beak, this industrious bird strips long, tough fibres of grass and palm leaves. Holding one blade steady with its claws, it weaves another strand over and under, tying intricate loops and knots. It constructs a magnificent hanging pouch nest complete with a secure nursery chamber and a downward tube entrance to protect eggs from predators. Nature is the original master weaver!', 'lecture_script': "Introduces natural architectural weaving, highlighting the male baya weaverbird's technique of stripping grass and interlacing strands over-and-under to construct suspended pouch nests.", 'checkpoints': [{'question': 'How does the male baya weaver construct its intricate hanging pouch nest?', 'options': ['By digging deep burrows under the earth', 'By weaving long grass and palm leaf strips over and under each other with its beak', 'By sticking large rocks together with mud', 'By collecting plastic bags from roadsides'], 'correct': 1, 'explanation': 'The baya weaver uses its sharp beak to harvest flexible grass ribbons, looping and interlacing them over and under in a true weaving pattern.', 'study_insight': 'Male weaverbirds often paste wet mud blobs inside the nest walls; scientists believe this adds ballast against heavy winds and balances the structure.'}, {'question': 'Why do baya weaverbirds typically build their hanging nests on branches dangling over water bodies?', 'options': ['To prevent tree snakes, monkeys, and ground predators from reaching their eggs and chicks', 'To wash their feathers before entering the nest', 'Because grass only grows underwater', 'To catch swimming fish from the doorway'], 'correct': 0, 'explanation': 'Suspended branches over rivers or ponds prevent land-based predators like snakes and rodents from easily raiding the nesting chamber.', 'study_insight': 'Spiders are another ancient weaver in nature, using liquid protein extruded from spinnerets to weave elastic orb webs to capture prey.'}]}, {'id': 2, 'title': 'Warp and Weft', 'subtitle': 'The Art of Weaving: Orthogonal Interlacing of Threads to Create Fabric', 'concept_html': '\n            <p>Every piece of woven cloth—from your school uniform shirt to a cotton bedsheet or a bamboo basket—is constructed using one timeless geometric principle: <strong>weaving</strong>.</p>\n            <div class="p-3.5 my-3 rounded-2xl bg-cyan-950/40 border border-cyan-500/40">\n                <span class="text-xs font-bold text-cyan-300 block mb-1">Scientific Definition of Weaving:</span>\n                <p class="text-xs text-slate-200 leading-relaxed">\n                    <strong>Weaving</strong> is the process of interlacing two distinct sets of threads or strips at right angles (perpendicularly) to form a unified, continuous textile fabric, mat, or basket.\n                </p>\n            </div>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">⬆️ The Warp (Tana)</span>\n                    <p class="text-xs text-slate-300">\n                        The vertical or lengthwise set of parallel threads held stationary under tension across the frame or loom.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">➡️ The Weft (Bana)</span>\n                    <p class="text-xs text-slate-300">\n                        The horizontal or crosswise thread carried back and forth by a shuttle, passing alternately <em>over and under</em> each warp yarn.\n                    </p>\n                </div>\n            </div>\n            <p>In <strong>Activity 1: Paper Strip Weaving</strong>, students cut vertical slits into a colored paper sheet (warp) and thread horizontal contrasting paper strips (weft) over and under to create checkered mats!</p>\n        ', 'spoken_text': 'What makes a shirt, a towel, or a grass mat hold together? It is the geometry of weaving! Weaving requires two distinct sets of yarns crossing each other at ninety-degree right angles. The vertical threads stretched tightly along the length of the loom are called the warp, or tana in Hindi. The horizontal thread passed back and forth across them is called the weft, or bana. As the shuttle carries the weft over one warp yarn and under the next, the loose strands lock securely together, transforming hundreds of fragile individual threads into a strong, flexible sheet of wearable fabric!', 'lecture_script': 'Defines weaving through the two orthogonal thread components: longitudinal warp (tana) and transversal weft (bana), explaining the over-and-under locking mechanism.', 'checkpoints': [{'question': 'In weaving technology, what are the lengthwise vertical threads held under tension on a loom called?', 'options': ['The warp (or tana)', 'The weft (or bana)', 'The sewing needle', 'The scissor blade'], 'correct': 0, 'explanation': 'The warp consists of longitudinal parallel yarns stretched along the loom, while the weft is passed perpendicularly over and under them.', 'study_insight': 'Warp yarns must withstand significant mechanical tension during weaving, so they are typically spun stronger and tighter than weft yarns.'}, {'question': 'What is the purpose of Activity 1 (Paper Strip Weaving) in Class 5 Science?', 'options': ['To demonstrate how interlacing horizontal and vertical strips over and under forms a unified sheet of fabric', 'To test which paper burns the fastest', 'To make paper completely dissolve in water', 'To create a flying paper aeroplane'], 'correct': 0, 'explanation': 'Weaving paper strips demonstrates tactile, hands-on understanding of how orthogonal over-and-under interlacing locks loose strands into a sturdy cohesive mat.', 'study_insight': 'Basketry and cane furniture use this identical over-and-under weaving principle with thicker botanical stems like willow, bamboo, and rattan.'}]}, {'id': 3, 'title': 'Handloom Heritage', 'subtitle': '4,000 Years of Indian Weaving: Kanjeevaram, Pashmina & Ikat Traditions', 'concept_html': '\n            <p>India is universally recognized as the cradle of global cotton and silk textiles. Archaeological excavations at Mohenjo-daro and Harappa prove that Indian craftspeople have operated <strong>handlooms for over 4,000 years</strong>!</p>\n            <div class="grid grid-cols-1 sm:grid-cols-3 gap-2.5 my-3 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-amber-400 block mb-1">🏛️ Kanjeevaram (Tamil Nadu)</span>\n                    <span class="text-slate-300">Woven from pure mulberry silk with three single threads twisted with silver-gold zari, featuring temple border motifs.</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-cyan-400 block mb-1">🏔️ Pashmina (Kashmir)</span>\n                    <span class="text-slate-300">Hand-spun from the ultra-fine downy undercoat of Himalayan Changthangi mountain goats, renowned for ethereal featherlight warmth.</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-rose-400 block mb-1">🎨 Ikat / Patola (Odisha & Gujarat)</span>\n                    <span class="text-slate-300">Complex resist tie-dyeing of individual warp and weft yarns <em>before</em> weaving so vivid geometric patterns align on the loom!</span>\n                </div>\n            </div>\n            <p>A traditional handloom is operated manually using foot pedals (treddles) and wooden shuttles, requiring zero electricity and sustaining millions of rural artisan families.</p>\n        ', 'spoken_text': "Step into India's four-thousand-year-old textile heritage! For millennia, our motherland has been the world's epicentre of exquisite handcrafted fabrics. Handloom weavers create legendary regional masterpieces: in Tamil Nadu, master weavers interlace pure mulberry silk and golden zari into heavy, lustrous Kanjeevaram sarees with temple borders. High in the cold Himalayas of Kashmir, artisans weave ultra-fine Pashmina shawls from the downy undercoat of mountain goats. In Odisha and Gujarat, weavers practice the breathtaking art of Ikat, tie-dyeing individual threads with mathematical precision before weaving them together. Every handloom cloth is a living canvas of Indian art!", 'lecture_script': 'Celebrates 4,000 years of Indian handloom heritage, exploring regional masterpieces including Kanjeevaram mulberry silk, Kashmiri Pashmina cashmere, and Odisha/Gujarat tie-dye Ikat.', 'checkpoints': [{'question': 'From which animal is genuine, ultra-soft Kashmiri Pashmina wool collected?', 'options': ['The fine undercoat of Changthangi mountain goats living at high altitudes in Ladakh and Kashmir', 'Domestic sheep living in coastal deserts', 'Wild desert camels', 'Himalayan snow leopards'], 'correct': 0, 'explanation': 'Pashmina is harvested from the ultra-fine winter down underfleece shed naturally by Changthangi goats grazing at elevations above 4,000 metres.', 'study_insight': 'A single Pashmina wool fibre is approximately 12 to 15 microns thick—six times finer than a strand of human hair!'}, {'question': "What makes the 'Ikat' weaving tradition of Odisha and Gujarat distinct from ordinary printed fabrics?", 'options': ['Individual warp and weft threads are tied and dyed in precise patterns BEFORE being woven on the loom', 'Fabric is painted using chemical sprays after it is stitched into clothes', 'Threads are glued together using tree sap without any loom', 'Clothes are woven only from melted plastic ropes'], 'correct': 0, 'explanation': 'Ikat is a complex resist-dyeing technique where yarns are mathematically bundled, tied, and dyed prior to weaving, producing blurred feathered motifs when woven.', 'study_insight': 'Double Ikat (such as Patan Patola of Gujarat) requires both warp and weft threads to be independently tie-dyed, aligning perfectly during weaving.'}]}, {'id': 4, 'title': 'Charkha Spinning', 'subtitle': "Drawing and Twisting Fibres: Spindles, Charkhas & Gandhi's Khadi Freedom", 'concept_html': '\n            <p>Before any fabric can be woven, loose fluffy fibres must be converted into continuous, durable yarn. This transformative process is called <strong>spinning</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🌀 Pulling and Twisting Mechanics</span>\n                    <p class="text-xs text-slate-300">\n                        A raw cotton ball pulled apart is delicate and tears easily. But when you simultaneously <strong>pull out a slender strand and twist it</strong>, friction between overlapping microscopic fibres binds them together into strong, unbreakable thread!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🇮🇳 The Charkha & Khadi Movement</span>\n                    <p class="text-xs text-slate-300">\n                        From simple hand spindles (takli) evolved the traditional wooden <strong>charkha (spinning wheel)</strong>. Mahatma Gandhi championed the charkha and handspun <strong>Khadi</strong> cloth as a supreme symbol of self-reliance (Atmanirbhar), rural dignity, and peaceful freedom from foreign goods.\n                    </p>\n                </div>\n            </div>\n            <p>Today, spinning is performed by massive high-speed industrial ring frames that spin hundreds of kilometres of fine yarn every hour.</p>\n        ', 'spoken_text': 'How do fluffy, cloud-like cotton bolls become strong sewing thread? Through the magic of spinning! If you simply pull raw cotton, it breaks apart. But when you pull out a few fibres and twist them between your fingers, microscopic ridges on the cotton fibres interlock tightly. Twisting creates immense friction, turning delicate fuzz into strong yarn! Centuries ago, people spun yarn using a simple hand spindle called a takli, followed by the wooden spinning wheel, or charkha. Mahatma Gandhi made the charkha and handspun Khadi cloth a national symbol of Indian self-reliance, freedom, and rural self-respect.', 'lecture_script': "Explains the mechanical physics of spinning (drawing out and twisting fibres to create interlocking frictional strength), the hand spindle (takli), the charkha, and Gandhi's Khadi movement.", 'checkpoints': [{'question': 'What physical action converts loose, fragile cotton fibres into strong, durable yarn during spinning?', 'options': ['Drawing out fibres while simultaneously twisting them to create interlocking friction', 'Soaking fibres in cold water until they freeze solid', 'Hammering fibres flat with heavy iron stones', 'Painting fibres with bright red oil paint'], 'correct': 0, 'explanation': 'Spinning draws out parallel strands and twists them together; the spiral twist forces microscopic surface scales to interlock, providing tensile strength.', 'study_insight': 'You can experience spinning with your own fingers by gently twisting cotton wool while pulling it outward—it instantly turns into sturdy string!'}, {'question': 'Why did Mahatma Gandhi promote the Charkha and Khadi cloth across India during the Independence movement?', 'options': ['As a national symbol of self-reliance (Atmanirbhar), rural self-employment, and unity against foreign exploitation', 'Because there was a complete shortage of paper', 'Because he wanted everyone to wear raincoats', 'Because cotton only grew in one city'], 'correct': 0, 'explanation': 'Spinning Khadi empowered rural villagers economically and symbolized freedom from dependency on imported British machine-manufactured cloth.', 'study_insight': "The Indian National Flag originally featured the spinning Charkha in its central white band before it was updated to Emperor Ashoka's 24-spoke Chakra."}]}, {'id': 5, 'title': 'Natural Fibres', 'subtitle': "Earth's Bounty: Plant Cellulose (Cotton, Flax, Jute) & Animal Proteins (Wool, Silk)", 'concept_html': '\n            <p>Every textile material begins with raw <strong>fibres</strong>—slender, hair-like flexible strands. Natural fibres are harvested directly from botanical plants and living animals without industrial synthesis.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🌱 Plant Fibres (Cellulose Based)</span>\n                    <ul class="text-xs text-slate-300 space-y-1">\n                        <li><strong>Cotton:</strong> Fluffy seed pod hairs from cotton plants; breathable, soft, and absorbs sweat easily.</li>\n                        <li><strong>Linen (Flax):</strong> Strong bast fibres extracted from flax plant stems; crisp, cool, and durable.</li>\n                        <li><strong>Jute & Bamboo:</strong> Sturdy golden stem fibres used for eco-bags, ropes, mats, and sustainable apparel.</li>\n                    </ul>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🐑 Animal Fibres (Protein Based)</span>\n                    <ul class="text-xs text-slate-300 space-y-1">\n                        <li><strong>Wool:</strong> Curly keratin fleece sheared humanely from sheep, yak, and camels; traps pockets of insulating air.</li>\n                        <li><strong>Silk:</strong> Continuous shimmering protein filament extruded by silkworm caterpillars to build cocoons.</li>\n                    </ul>\n                </div>\n            </div>\n            <p>Natural fibres are 100% biodegradable: when discarded, soil microorganisms decompose them naturally without leaving toxic microplastics!</p>\n        ', 'spoken_text': 'Let us examine where our clothing fibres come from. Nature provides us with two major classes of natural fibres: plant fibres and animal fibres. Plant fibres, like soft cotton harvested from seed bolls, crisp linen obtained from flax plant stems, and golden jute, are made of plant cellulose. They are lightweight, highly breathable, and absorb sweat perfectly during hot Indian summers. Animal fibres, like wool sheared from sheep and yak, and shimmering silk produced by caterpillars, are made of natural proteins. Wool fibres are crimped, trapping pockets of still air to keep our bodies warm in winter!', 'lecture_script': 'Classifies natural fibres into plant-based cellulose (cotton, linen, jute, bamboo) and animal-based protein (wool, silk), detailing their physical properties and biodegradability.', 'checkpoints': [{'question': 'Which of the following is an example of a natural plant fibre harvested directly from seed pods?', 'options': ['Cotton', 'Nylon', 'Polyester', 'Wool'], 'correct': 0, 'explanation': 'Cotton grows as protective soft fluffy fibres surrounding the seeds of the Gossypium cotton plant.', 'study_insight': "India is the world's largest producer of cotton, with the black regur soil of Gujarat, Maharashtra, and Telangana offering ideal growing conditions."}, {'question': 'Why do woolen sweaters keep us comfortably warm during chilly winter mornings?', 'options': ['Curly, crimped wool fibres trap millions of microscopic pockets of still air, which is an excellent thermal insulator', 'Wool contains tiny internal electric heaters', 'Wool radiates green nuclear light', 'Wool turns cold air into steam'], 'correct': 0, 'explanation': 'Trapped air is a very poor conductor of heat. The crimped structure of wool fibers creates air cushions that prevent body heat from escaping.', 'study_insight': 'Unlike synthetic garments, natural wool and cotton garments naturally decompose in composting soil within a few months.'}]}, {'id': 6, 'title': 'Silk Cocoon', 'subtitle': 'Sericulture: The Metamorphic Life Cycle of the Bombyx mori Silkmoth', 'concept_html': '\n            <p>Silk is celebrated as the \'Queen of Textiles\' for its shimmering elegance and featherlight tensile strength. The production of silk from the silkworm is an agricultural science called <strong>sericulture</strong>.</p>\n            <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 my-3 text-xs text-center">\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-base block mb-1">🥚</span>\n                    <span class="font-bold text-amber-400 block">1. Egg</span>\n                    <span class="text-slate-400 text-[10px]">Female moth lays 300-500 tiny eggs</span>\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-base block mb-1">🐛</span>\n                    <span class="font-bold text-emerald-400 block">2. Caterpillar</span>\n                    <span class="text-slate-400 text-[10px]">Feeds voraciously on fresh mulberry leaves for 30 days</span>\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-base block mb-1">🧶</span>\n                    <span class="font-bold text-cyan-400 block">3. Cocoon</span>\n                    <span class="text-slate-400 text-[10px]">Spins a 1,000 m continuous protein filament around itself</span>\n                </div>\n                <div class="p-2 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-base block mb-1">🦋</span>\n                    <span class="font-bold text-purple-400 block">4. Adult Moth</span>\n                    <span class="text-slate-400 text-[10px]">Metamorphoses into pupa and emerges as adult silk moth</span>\n                </div>\n            </div>\n            <p>The caterpillar moves its head in a figure-eight (8) motion, secreting liquid protein (fibroin and sericin) from salivary glands that hardens upon contact with air into shimmering silk filament.</p>\n        ', 'spoken_text': 'Discover the incredible secret of silk! Silk is spun by a small creature: the caterpillar of the silk moth, Bombyx mori. A mother moth lays hundreds of tiny eggs. When they hatch, the ravenous caterpillars feed non-stop on fresh green mulberry leaves for four weeks, growing thousands of times their original weight! Ready to pupate, the caterpillar weaves a protective oval home called a cocoon. Moving its head in figure-eight patterns, it extrudes a continuous liquid protein thread from its glands that hardens in the air. A single unbroken silk thread from one cocoon can measure nearly one kilometre in length!', 'lecture_script': 'Outlines sericulture and the complete 4-stage metamorphic life cycle of the Bombyx mori silkmoth: egg, voracious mulberry-eating caterpillar, protein cocoon spinning, and adult moth.', 'checkpoints': [{'question': 'What primary food do silkworm caterpillars eat voraciously before spinning their silk cocoons?', 'options': ['Fresh green mulberry leaves', 'Dry wheat flour grains', 'Sugarcane juice drops', 'Neem tree bark'], 'correct': 0, 'explanation': 'Silkworms (Bombyx mori) feed almost exclusively on the nutritious leaves of the white mulberry tree (Morus alba) to build protein reserves.', 'study_insight': 'India produces four diverse varieties of natural silk: Mulberry, Tasar (wild forest silk), Muga (golden silk of Assam), and Eri (peace silk).'}, {'question': 'What geometric pattern does a silkworm caterpillar trace with its head while spinning its silk cocoon?', 'options': ['A continuous figure-eight (8) pattern', 'A perfect straight triangle', 'A zigzag staircase', 'It holds its head completely still'], 'correct': 0, 'explanation': 'The caterpillar swings its head in regular figure-8 loops to distribute the liquid fibroin filament evenly around its body into an oval cocoon shell.', 'study_insight': 'A single continuous strand of silk reeled from one cocoon can extend between 800 and 1,200 metres!'}]}, {'id': 7, 'title': 'Synthetic Fibres', 'subtitle': 'Human-Made Polymers: Nylon, Rayon, Polyester & Petroleum Chemistry', 'concept_html': '\n            <p>While natural fibres have clothed humanity for thousands of years, modern chemists invented <strong>synthetic (man-made) fibres</strong> in industrial laboratories using petrochemicals.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🧪 Chemical Polymer Synthesis</span>\n                    <ul class="text-xs text-slate-300 space-y-1">\n                        <li><strong>Nylon:</strong> First fully synthetic polymer; ultra-strong, elastic, used for parachutes, ropes, and toothbrushes.</li>\n                        <li><strong>Polyester & Terylene:</strong> Wrinkle-free, dries exceptionally fast; common in sportswear and raincoats.</li>\n                        <li><strong>Rayon (Artificial Silk):</strong> Semi-synthetic fibre regenerated from processed wood pulp cellulose; soft and shiny.</li>\n                    </ul>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">⚖️ Advantages vs Disadvantages</span>\n                    <p class="text-xs text-slate-300">\n                        <strong>Pros:</strong> Highly durable, moth-resistant, wrinkle-free, and affordable.<br>\n                        <strong>Cons:</strong> Poor breathability (traps sweat), melts and sticks to skin when exposed to kitchen fire, and sheds non-biodegradable microplastics into oceans!\n                    </p>\n                </div>\n            </div>\n            <p><strong>Safety Warning:</strong> Never wear synthetic polyester or nylon clothes while working in the kitchen near gas stoves or lighting Diwali crackers!</p>\n        ', 'spoken_text': 'Now let us examine human-made synthetic fibres. In the twentieth century, chemists invented fibres synthesized from petroleum chemicals, called synthetic polymers. The most famous include nylon, polyester, acrylic, and terylene. Synthetic fibres have remarkable advantages: they are extraordinarily strong, wrinkle-resistant, insect-proof, and dry in minutes after washing. But they have critical drawbacks: synthetic fabrics do not absorb sweat well, making them clammy in hot weather. More dangerously, synthetic clothes melt like hot plastic when exposed to flame, sticking painfully to human skin. Always wear natural cotton clothes when near kitchen stoves or fire!', 'lecture_script': 'Contrasts synthetic petrochemical fibres (nylon, polyester, terylene, rayon) with natural fibres, examining their tensile strength, low breathability, and dangerous fire melting hazards.', 'checkpoints': [{'question': 'What is a major safety danger of wearing synthetic fabrics like nylon and polyester near open flames or kitchen stoves?', 'options': ['Synthetic fibres melt rapidly into hot sticky liquid that clings to the skin, causing severe burns', 'Synthetic fabrics turn into ice water', 'Synthetic clothes become five times heavier', 'They immediately change colour to bright blue'], 'correct': 0, 'explanation': 'Because synthetics are thermoplastic polymers, exposure to fire causes them to melt and fuse into flesh rather than charring into ash like natural cotton.', 'study_insight': 'Firefighters, chefs, and laboratory scientists always wear 100% natural treated cotton or fire-retardant aramid fibers for thermal protection.'}, {'question': 'Which of the following is an advantage of synthetic polyester sportswear over pure natural cotton?', 'options': ['It dries very quickly after washing, resists wrinkles, and has high tensile strength', 'It is made by silkworms in gardens', 'It decomposes in garden soil within two days', 'It grows on mulberry trees'], 'correct': 0, 'explanation': 'Polyester does not absorb moisture into its polymer chains (hydrophobic), allowing wash water and sweat to evaporate rapidly from its surface.', 'study_insight': "Rayon is unique as a 'semi-synthetic' fibre: it is manufactured from natural wood pulp cellulose that has been chemically dissolved and extruded."}]}, {'id': 8, 'title': 'Tailorbird Stitches', 'subtitle': 'Natural Craftsmanship: Orthotomus sutorius Stitching Leaves with Silk', 'concept_html': '\n            <p>Just as the baya weaver bird inspired human weaving, another tiny winged neighbor inspired human stitching: the lively <strong>common tailorbird (Orthotomus sutorius)</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🪡 Needle-Like Beak Punctures</span>\n                    <p class="text-xs text-slate-300">\n                        This restless, olive-green songbird selects two large living leaves on a garden shrub. Using its long, slender, curved beak like an awl or cobbler\'s needle, it punctures a neat line of tiny matching eyelet holes along the leaf margins!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🧵 Spider Silk Knots & Rivets</span>\n                    <p class="text-xs text-slate-300">\n                        For thread, the tailorbird gathers sticky cobweb silk, fine plant fibres, or cotton lint. Pulling the strand through the punctured holes, the bird tugs on the end to form a tangled little fuzzy knot (rivet) that stops the thread from slipping out, pulling the green leaves into a concealed cradling cup!\n                    </p>\n                </div>\n            </div>\n            <p>Inside this stitched living cradle, the tailorbird lines the pouch with soft kapok fluff and feathers, keeping its hatchlings safely hidden from marauding crows and cats.</p>\n        ', 'spoken_text': "Meet nature's most skilled tailor: the common tailorbird! Flitting through Indian gardens with an upright cocked tail, this small olive-green bird builds its nest through genuine stitching. The tailorbird selects two broad green leaves on a plant. Using its sharp, slender beak like a sewing needle, it punches neat holes along the edges of both leaves. Next, it collects sticky spider cobwebs or cotton threads. Threading the fibre through the holes, it tangles the ends into fuzzy little knots that prevent the thread from pulling back out. It stitches the two leaves tightly together into a green sleeve, then pads the inside with soft feathers to cradle its babies!", 'lecture_script': 'Examines the nesting biology of the common tailorbird, detailing its needle-like beak punching leaf eyelets and using spider silk/cotton threads with knotted rivets to stitch living leaves together.', 'checkpoints': [{'question': 'How does the tailorbird create eyelet holes along the edges of broad leaves?', 'options': ['By puncturing them with its sharp, slender, needle-like beak', 'By burning holes with hot embers', 'By chewing holes with large teeth', 'By dropping stones from the sky'], 'correct': 0, 'explanation': 'The tailorbird uses its thin, pointed bill as a surgical puncture awl to make evenly spaced holes along the leaf margins.', 'study_insight': 'The tailorbird chooses living leaves still attached to the plant stem so the cradle remains fresh, green, and camouflaged among garden foliage.'}, {'question': 'What material does the tailorbird collect to use as sewing thread to join the punctured leaves?', 'options': ['Sticky spider silk, fine plant fibres, and soft cotton lint', 'Thick iron wire cables', 'Nylon fishing lines bought from shops', 'Strips of copper metal'], 'correct': 0, 'explanation': 'The tailorbird gathers sticky cobweb strands and natural plant fibers, threading them through the leaf holes and forming knots to lock them in place.', 'study_insight': 'Human tailors adopted this exact technique thousands of years ago, using bone needles and animal sinew before metal needles and cotton thread were invented.'}]}, {'id': 9, 'title': 'Running Stitch', 'subtitle': 'Activity 7 & 8: Basic Needlework & Upcycling Scraps into Functional Mats', 'concept_html': '\n            <p>While weaving creates continuous sheets of cloth, <strong>stitching</strong> uses a pointed needle and thread to join two or more pieces of fabric together, hem borders, or mend tears.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🪡 The Running Stitch (Kacha Tanka)</span>\n                    <p class="text-xs text-slate-300">\n                        In <strong>Activity 7</strong>, students learn the foundational hand stitch: the <strong>running stitch</strong>. The needle passes smoothly <em>in and out</em> (up and down) through the cloth in a continuous straight line, creating evenly spaced dashes of thread on both sides!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🧵 Joining Tailor\'s Fabric Scraps</span>\n                    <p class="text-xs text-slate-300">\n                        In <strong>Activity 8</strong>, students collect leftover colorful cloth scraps (chindi) from local tailor shops. By stitching multiple rectangular pieces side-by-side using running stitches, small discarded cut-offs are upcycled into durable table mats, potholders, or cleaning cloths!\n                    </p>\n                </div>\n            </div>\n            <p>Every complex garment—from shirts and trousers to quilts—relies on basic stitches holding pieces together along structural seams.</p>\n        ', 'spoken_text': "Now pick up a needle and thread in Activities 7 and 8 to master basic stitching! Threading cotton yarn through a steel needle's eye and tying a secure knot at the base, we practice the fundamental running stitch. The needle glides into the fabric from underneath, comes up on top, dives down again, and re-emerges in a clean straight rhythm: up, down, up, down! By connecting leftover colorful fabric scraps from neighborhood tailor shops with running stitches, we can craft delightful checkered floor mats, coasters, and tablecloths. Stitching breathes new, useful life into discarded cloth!", 'lecture_script': 'Introduces hand stitching through Activity 7 (the up-and-down rhythm of the running stitch) and Activity 8 (piecing together tailor fabric scraps into functional household textiles).', 'checkpoints': [{'question': "What is the defining mechanical pattern of a simple 'running stitch' across fabric?", 'options': ['Passing the needle and thread up and down through the cloth in a continuous straight line', 'Tying fifty knots on top of each other in one single spot', 'Cutting circular holes into the fabric with scissors', 'Gluing plastic tape across the border'], 'correct': 0, 'explanation': 'A running stitch involves passing the needle in and out of the fabric at regular intervals in a straight or curved line.', 'study_insight': 'A thimble is a pitted metal or rubber cup worn over the middle fingertip to push needles through thick fabric without pricking skin.'}, {'question': 'In Activity 8, what useful household items can students create by stitching leftover tailor fabric scraps together?', 'options': ['Useful table mats, cleaning cloths, patchwork coasters, and pot holders', 'Heavy concrete garden bricks', 'Drinking water glasses', 'Metal cooking pans'], 'correct': 0, 'explanation': 'Patchwork stitching joins small discarded fabric scraps into large, durable, washable household textiles, preventing fabric waste.', 'study_insight': 'Patchwork quilting has been practiced in rural India for centuries, creating famous layered winter quilts known as Godharis.'}]}, {'id': 10, 'title': 'Chikankari Craft', 'subtitle': 'Regional Embroideries: Lucknow Chikankari & Rajasthani Banjara Mirror Art', 'concept_html': '\n            <p>Across India, needle and thread do far more than merely join fabric—they become brushes for exquisite storytelling through <strong>traditional embroidery</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🕊️ Chikankari (Lucknow, Uttar Pradesh)</span>\n                    <p class="text-xs text-slate-300">\n                        World-famous delicate white-on-white embroidery traditionally executed on translucent cotton muslin or georgette. Master artisans use 36 distinct stitches (such as <em>Bakhiya</em> or shadow stitch, <em>Phanda</em> knots, and <em>Jaali</em> lattice work) depicting delicate floral vines, paisleys, and peacocks.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🪞 Banjara Embroidery (Rajasthan)</span>\n                    <p class="text-xs text-slate-300">\n                        Vibrant, bold folk embroidery crafted by the nomadic Banjara community. It features brilliant geometric diamond stitches, bright yellow and red threads, cowrie shells, and small reflective circular <strong>mirrors (abhla)</strong> locked in place by herringbone stitches to reflect desert sunshine!\n                    </p>\n                </div>\n            </div>\n            <p>Both styles reflect their regional geographic spirit: the serene refined breeze of the Awadh royal courts versus the radiant desert celebrations of Rajasthan.</p>\n        ', 'spoken_text': 'Travel across India to explore regional embroideries! In the historic city of Lucknow, Uttar Pradesh, artisans craft delicate Chikankari. Using fine white cotton thread on soft muslin, they stitch gossamer shadow-work vines, delicate flower buds, and lattice jaali patterns that look like morning mist over flowers. Journey west into the sun-drenched sands of Rajasthan, and the embroidery transforms into the energetic, colorful Banjara craft! Nomadic women stitch vibrant yellow, crimson, and green geometric lines embedded with tiny shimmering glass mirrors and cowrie shells, catching the golden desert sunlight as they walk!', 'lecture_script': 'Explores two contrasting Indian embroidery traditions: Lucknow Chikankari (delicate white-on-white floral shadow work) and Rajasthani Banjara (vibrant geometric mirror-work embroidery).', 'checkpoints': [{'question': "Which historic Indian city is world-renowned for the delicate white-on-white shadow embroidery known as 'Chikankari'?", 'options': ['Lucknow, Uttar Pradesh', 'Chennai, Tamil Nadu', 'Shimla, Himachal Pradesh', 'Panaji, Goa'], 'correct': 0, 'explanation': 'Lucknow is the traditional home of Chikankari embroidery, refined under the patronage of the Nawabs of Awadh over centuries.', 'study_insight': 'In Chikankari shadow work (Bakhiya), the herringbone stitch is worked on the reverse side of sheer muslin so only a delicate shadow outline shows on the front.'}, {'question': 'What sparkling decorative elements are characteristically stitched into traditional Banjara embroidery from Rajasthan?', 'options': ['Small circular reflective glass mirrors (abhla) and cowrie shells', 'Heavy iron building bolts', 'Fresh flower petals that wilt in an hour', 'Electronic LED computer chips'], 'correct': 0, 'explanation': 'Banjara embroidery secures small glass mirrors with intricate needlework, reflecting light and traditionally believed to ward off evil spirits.', 'study_insight': 'Traditional mirrors were originally crafted by blowing thin glass globes coated on the inside with reflective zinc or lead, then cutting them into round discs.'}]}, {'id': 11, 'title': 'Kantha Quilts', 'subtitle': 'Storytelling Textiles: Eastern Indian Kantha & Rajasthani Gota Patti', 'concept_html': '\n            <p>Indian embroidery traditions transform everyday household needs into priceless cultural artworks celebrating domestic love and royal elegance.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🧵 Kantha (West Bengal, Odisha & Tripura)</span>\n                    <p class="text-xs text-slate-300">\n                        Born from the sacred tradition of upcycling, rural women layer multiple soft, worn cotton sarees and dhotis. Using thread pulled from the saree borders, they quilt the layers together using rippling <strong>running stitches</strong> depicting folk tales, rural life, birds, elephants, and lotus blooms!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">👑 Gota Patti (Rajasthan)</span>\n                    <p class="text-xs text-slate-300">\n                        A regal applique technique originating in Rajasthan. Gold and silver metallic ribbons (zari tape) are cut into small floral petal shapes (patti), folded, and stitched onto rich silk, chiffon, or bandhani turbans and lehengas for grand festive celebrations.\n                    </p>\n                </div>\n            </div>\n            <p>Kantha turns everyday discarded fabrics into heirloom family treasures, while Gota Patti brings royal metallic grandeur to festive weddings.</p>\n        ', 'spoken_text': 'Observe two more magnificent textile traditions: Kantha of Eastern India and Gota Patti of Rajasthan. In the green villages of West Bengal, Odisha, and Tripura, women take old, soft cotton sarees that have become supple with washing. They layer three or four sarees together, and using colourful threads pulled directly from the borders, they quilt the entire fabric with endless ripples of running stitches! These Kantha quilts depict village scenes, playful peacocks, and auspicious lotus flowers. Meanwhile, in royal Rajasthan, artisans craft Gota Patti by cutting shiny gold and silver ribbons into shimmering petal shapes, stitching them onto festive silks for weddings!', 'lecture_script': 'Examines Eastern Indian Kantha (upcycled layered saree quilts stitched with pictorial running stitches) and Rajasthani Gota Patti (applique ribbon art with metallic petal motifs).', 'checkpoints': [{'question': "How did traditional 'Kantha' embroidery originate in the homes of West Bengal, Odisha, and Tripura?", 'options': ['By layering worn, soft cotton sarees and quilting them together with continuous decorative running stitches', 'By printing designs on plastic sheets with computers', 'By knitting sweaters with thick mountain wool', 'By melting gold coins onto cotton robes'], 'correct': 0, 'explanation': 'Kantha is an ancient upcycling art where rural women stitch layered old sarees with embroidered storytelling motifs to create warm baby wraps and quilts.', 'study_insight': 'A Nakshi Kantha is a specialized narrative quilt where every embroidered motif illustrates folk stories, wedding rituals, or rural agricultural life.'}, {'question': "What is the defining visual characteristic of Rajasthani 'Gota Patti' textile craftsmanship?", 'options': ['Gold and silver metallic ribbon tape cut into petal and leaf shapes and appliqued onto festive fabrics', 'Coarse black wool woven into heavy carpets', 'Plain white threads stitched in straight hospital lines', 'Fabric dipped in black mud to create shadows'], 'correct': 0, 'explanation': 'Gota is woven metallic ribbon; artisans fold and cut it into leaf/petal (patti) shapes, stitching the edges onto silk or georgette.', 'study_insight': 'Gota patti gives garments the dazzling appearance of solid gold embroidery while remaining lightweight and flexible to wear.'}]}, {'id': 12, 'title': 'Phulkari Toda', 'subtitle': "Agrarian & Tribal Art: Punjab's Phulkari Gardens & Nilgiri Toda Shawls", 'concept_html': '\n            <p>From the golden wheat fields of Punjab to the misty Nilgiri hills of Tamil Nadu, needlework expresses regional cultural identity and tribal heritage.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🌸 Phulkari (Punjab)</span>\n                    <p class="text-xs text-slate-300">\n                        Literally meaning \'flower work\' (Phul + Kari). Women embroider vibrant geometric motifs using untwisted, glossy <strong>pat (floss silk)</strong> thread on coarse, homespun khaddar cotton. The darning stitch is worked entirely from the <em>reverse side</em> of the fabric without counting threads, creating a dense, velvety floral tapestry on the front!\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🏔️ Toda Embroidery (Pukhoor - Tamil Nadu)</span>\n                    <p class="text-xs text-slate-300">\n                        Practiced by the indigenous Toda pastoral tribe living in the Nilgiri highlands. Women embroider thick unbleached white cotton shawls (Poothkuli) using solely <strong>red and black woollen threads</strong>, counting individual fabric warp threads to create striking geometric motifs resembling buffalo horns and celestial stars.\n                    </p>\n                </div>\n            </div>\n            <p>A Punjabi bride receives an heirloom Bagh or Phulkari from her maternal grandmother, while a Toda shawl is a sacred life-long identity wrapped during tribal ceremonies.</p>\n        ', 'spoken_text': "Experience the festive colors of Punjab and the sacred tribal heritage of the Nilgiri mountains! In Punjab, women create Phulkari, which means 'flower crafting'. Using lustrous, untwisted silk floss on handspun cotton shawls, they embroider dazzling geometric diamonds and marigold gardens. Wonderfully, the embroiderer works completely from the back of the cloth, counting threads in her mind! Now travel south to the misty Nilgiri hills of Tamil Nadu, home to the ancient Toda pastoral tribe. Toda women embroider thick white shawls using only deep red and black wool. They count every weave thread to create bold, striking geometric patterns representing sacred buffalo horns and stars!", 'lecture_script': "Contrasts Punjab's Phulkari (silk-floss floral darning stitch on khaddar cotton) with the Toda tribe's Pukhoor embroidery of the Nilgiris (red-and-black counted-thread geometric motifs on white shawls).", 'checkpoints': [{'question': "What does the word 'Phulkari' from Punjab literally translate to in English?", 'options': ['Flower work (Phul = flower, Kari = craft)', 'Ocean wave', 'Desert sand', 'Running river'], 'correct': 0, 'explanation': "Phulkari literally translates to 'flower work', celebrated for its rich, vibrant floral embroidery covering shawls and dupattas.", 'study_insight': "When a Phulkari is so densely embroidered that the underlying base fabric is entirely hidden by silk stitches, it is reverently called a 'Bagh' (garden)."}, {'question': 'Which two specific thread colours do the indigenous Toda women of the Nilgiri hills use on their traditional white shawls?', 'options': ['Red and black', 'Bright neon green and purple', 'Yellow and pink', 'Gold and silver'], 'correct': 0, 'explanation': 'Toda embroidery (Pukhoor) strictly uses striking red and black woollen threads on unbleached white cotton, producing dramatic high-contrast geometric art.', 'study_insight': 'Toda embroidery has received Geographical Indication (GI) status in India, protecting the unique cultural intellectual heritage of the pastoral Nilgiri community.'}]}, {'id': 13, 'title': 'Kashmiri Khneng', 'subtitle': "Mountain Masterpieces: Kashmiri Kashida & Meghalaya's Khneng Eri Silk", 'concept_html': '\n            <p>From the northern snow-capped valleys to the misty cloud forests of Northeast India, regional stitching captures local biodiversity and endemic flora.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🍁 Kashmiri Kashida & Aari (Kashmir)</span>\n                    <p class="text-xs text-slate-300">\n                        Celebrated for intricate nature-inspired motifs: serrated chinár tree leaves, saffron flowers, almonds (badam), irises, and nightingales (bulbul). Stitched on woollen pashminas and pherans using fine single-needle satin stitches or hooked <strong>aari needles</strong> with fine silk and wool threads.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🐟 Khneng Embroidery (Meghalaya)</span>\n                    <p class="text-xs text-slate-300">\n                        An exceedingly rare, ancient embroidery preserved exclusively in the village of Mustoh in the Khasi Hills of Meghalaya. Stitched onto locally spun <strong>Eri peace silk</strong> shawls (Ryndia) using black wool, its geometric pattern mimics the delicate central spine and bones of a local river fish!\n                    </p>\n                </div>\n            </div>\n            <p>These embroidery traditions are not mere commercial garments; they are living botanical and zoological records of India\'s diverse regional ecosystems.</p>\n        ', 'spoken_text': 'Ascend into the crisp mountain air of Kashmir, where master needleworkers practice Kashida embroidery. Inspired by the paradise gardens of the valley, their delicate needles trace rust-red maple-like chinár leaves, blooming saffron blossoms, ripe almonds, and singing nightingales on warm woollen pherans. Now journey across the country to the Khasi hills of Meghalaya! In the remote village of Mustoh, Khasi artisans practice an extraordinary embroidery called Khneng. Stitched onto cream-colored Eri peace silk using black thread, Khneng patterns faithfully depict the delicate backbone and ribs of a local river fish. It is an ancient textile homage to river ecology!', 'lecture_script': "Explores Kashmiri Kashida (chinar leaf, saffron, and nightingale motifs on wool) and Meghalaya's rare Khneng embroidery (fish-bone motifs stitched on Eri peace silk in Mustoh village).", 'checkpoints': [{'question': 'Which iconic leaf motif inspired by Himalayan deciduous trees is frequently featured in Kashmiri Kashida embroidery?', 'options': ['The serrated Chinár (oriental plane tree) leaf', 'The cactus leaf', 'The banana leaf', 'The sea palm leaf'], 'correct': 0, 'explanation': 'The majestic chinar tree, whose leaves turn golden-red in autumn, is the most celebrated nature motif in Kashmiri carpets, shawls, and woodwork.', 'study_insight': "Kashmiri artisans often use an 'Aari'—a fine hook needle that creates continuous chain-stitch loops rapidly across thick woollen carpets and shawls."}, {'question': "What natural ecological feature does the ancient 'Khneng' embroidery of Meghalaya depict on Eri silk shawls?", 'options': ['The backbone and rib skeleton of a local freshwater river fish', 'A soaring eagle with giant wings', 'A tiger catching deer', 'A blooming desert cactus'], 'correct': 0, 'explanation': 'Khneng embroidery, unique to Mustoh village in Meghalaya, consists of fine geometric needlework representing the spine of a local riverine fish on traditional Ryndia silk.', 'study_insight': "Eri silk is known as 'peace silk' or Ahimsa silk because the caterpillar naturally cuts its way out of the cocoon as a moth before the silk is reeled, without harming the insect."}]}, {'id': 14, 'title': 'Cloth Upcycling', 'subtitle': 'Sustainable Traditions: Hand-Me-Downs, Godharis & Zero-Waste Culture', 'concept_html': '\n            <p>Long before \'sustainability\' became a global buzzword, Indian households practiced an unbroken tradition of <strong>zero-waste circular fashion</strong>.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-3 gap-2.5 my-3 text-xs">\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-emerald-400 block mb-1">👶 1. Hand-Me-Downs</span>\n                    <span class="text-slate-300">Clothes outgrown by older siblings or cousins are lovingly passed down. Softened through repeated washings, they are gentler on young children\'s skin!</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-amber-400 block mb-1">🪡 2. Godhari & Quilts</span>\n                    <span class="text-slate-300">Worn cotton sarees and dhotis are layered and quilted with running stitches into cozy patchwork blankets, mattress pads, and baby swaddles.</span>\n                </div>\n                <div class="p-2.5 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="font-bold text-cyan-400 block mb-1">🧹 3. Final Utility</span>\n                    <span class="text-slate-300">When fabric finally wears thin, it is repurposed as kitchen cleaning wipes, mop cloths (pocha), or cordage string—nothing is thrown away!</span>\n                </div>\n            </div>\n            <p>Fast fashion—buying cheap synthetic clothes and tossing them into landfills after a few wears—clogs global waterways with microplastics. Indian textile traditions show the world how to cherish every thread!</p>\n        ', 'spoken_text': "Consider the wise, sustainable traditions of Indian homes! In our culture, a piece of clothing is almost never casually thrown away. When an older brother or sister outgrows a sturdy shirt, it is lovingly handed down to a younger cousin. Worn cotton clothes, softened by years of washing, become tender swaddling blankets for newborn babies. When grandma's cotton sarees wear thin, they are layered and hand-quilted into beautiful Godhari blankets. Finally, scraps become cleaning cloths and kitchen dusters. Every single thread serves a lifelong purpose, keeping mountains of textile garbage out of our landfills!", 'lecture_script': 'Celebrates the traditional Indian circular textile lifecycle: hand-me-down clothing sharing, quilting old sarees into Godharis/blankets, and final repurposing into household cleaning cloths.', 'checkpoints': [{'question': 'Why is passing down outgrown clothes to younger siblings or relatives an ecologically sustainable practice?', 'options': ['It extends the useful life of garments, dramatically reducing textile waste, water consumption, and chemical dyeing pollution', 'It turns the clothes into solid gold', 'It makes the fabric heavier each year', 'It destroys the sewing stitches'], 'correct': 0, 'explanation': 'Reusing garments reduces demand for new manufacturing, conserving thousands of litres of water and preventing synthetic textiles from choking landfills.', 'study_insight': 'Manufacturing a single new cotton t-shirt requires approximately 2,700 litres of fresh water—enough drinking water for one person for two and a half years!'}, {'question': 'What traditional Indian quilted textile is created by layering and stitching worn-out cotton sarees and dhotis together?', 'options': ['A Godhari (or Kantha quilt)', 'A plastic raincoat', 'An iron door mat', 'A synthetic parachute'], 'correct': 0, 'explanation': 'A Godhari is a traditional quilted cotton blanket made by layering old sarees or dhotis and securing them with dense lines of running stitches.', 'study_insight': 'In traditional rural households, making a Godhari was a joyful social activity where mothers, aunts, and grandmothers sat together to quilt and sing songs.'}]}, {'id': 15, 'title': 'Fabric Testing', 'subtitle': 'Scientific Inquiry: Identifying Fibres by Touch, Weave Density & Flame Burn Test', 'concept_html': '\n            <p>How can a textile scientist determine whether an unknown fabric scrap is pure cotton, luxurious silk, warm wool, or synthetic polyester? Through <strong>scientific fibre testing</strong>!</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-cyan-400 block mb-1">🔍 Magnifier & Touch Test</span>\n                    <p class="text-xs text-slate-300">\n                        Under a magnifying lens, natural cotton shows twisted, ribbon-like fibres with matte texture. Silk filaments appear smooth, triangular, and lustrous. Synthetic polyester strands look like perfectly uniform, glassy plastic cylinders.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-rose-400 block mb-1">🔥 The Flame Burn Test (Scientific Forensic)</span>\n                    <ul class="text-xs text-slate-300 space-y-1">\n                        <li><strong>Cotton/Linen:</strong> Burns with a yellow flame, smells like burning paper (cellulose), leaves soft grey ash.</li>\n                        <li><strong>Silk/Wool:</strong> Burns slowly with self-extinguishing flame, smells like burning hair (protein), leaves dark crushable bead.</li>\n                        <li><strong>Synthetic Nylon/Polyester:</strong> Melts rapidly, drips like boiling plastic with chemical odor, forms hard black unbreakable bead!</li>\n                    </ul>\n                </div>\n            </div>\n            <p><strong>Safety Note:</strong> Burn tests must always be demonstrated by an adult teacher over a ceramic dish with cold water nearby.</p>\n        ', 'spoken_text': 'How do textile scientists identify mystery fabric scraps? Through careful observation and the famous burn test! Under a magnifying glass, natural cotton threads have tiny twists, while synthetic polyester looks like flawless, shiny plastic rods. In a controlled laboratory flame test, observe the smell and ash: cotton burns cleanly with a smell of burning paper and leaves soft grey ash, because it is plant cellulose! Wool and silk burn slowly with a smell of singed hair, because they are animal proteins. But watch out for synthetic polyester: it melts instantly into a hot, sticky chemical puddle and leaves a hard, sharp plastic bead!', 'lecture_script': 'Explains textile identification methodologies: tactile feel, magnifying weave analysis, and the laboratory flame burn test distinguishing plant cellulose, animal protein, and synthetic polymers.', 'checkpoints': [{'question': 'During a scientific flame burn test, what distinct odour does a pure cotton thread produce when burning?', 'options': ['It smells like burning paper or leaves, because cotton is composed of plant cellulose', 'It smells like sweet melted chocolate', 'It smells like fresh ocean seawater', 'It produces no smell at all'], 'correct': 0, 'explanation': 'Because cotton is nearly 90% pure plant cellulose (the exact same chemical polymer that makes paper and wood), it smells like burning paper and leaves soft ash.', 'study_insight': 'Protein fibres like wool and silk smell distinctly like burning feathers or hair during a flame test because they contain keratin and fibroin proteins rich in sulfur.'}, {'question': 'What residue is left behind when a synthetic polyester or nylon thread is burned?', 'options': ['A hard, round, uncrushable plastic bead formed from melted polymers', 'Fine, soft grey powder that dissolves in air', 'Cold drinking water', 'Solid copper metal wire'], 'correct': 0, 'explanation': 'Synthetic petrochemical fibres do not char into soft ash; instead, they melt into molten plastic that solidifies into a hard, rigid synthetic bead.', 'study_insight': 'A simple burn test requires only a tiny 2 cm yarn snippet held with metal tweezers over a flame-proof ceramic dish.'}]}, {'id': 16, 'title': 'Textile Guardians', 'subtitle': 'Mindful Fashion: Honoring Handloom Artisans & Practicing Conscious Clothing Care', 'concept_html': '\n            <p>We conclude our journey into clothes and craftsmanship by recognizing our role as <strong>Textile Guardians</strong>. A piece of clothing is never just cloth—it represents soil, water, agricultural labour, and artisan genius.</p>\n            <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 my-3">\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-amber-400 block mb-1">🧶 Valuing Every Individual Thread</span>\n                    <p class="text-xs text-slate-300">\n                        A single shirt contains over <strong>20 kilometres of spun yarn</strong>, woven across thousands of intersections. Respecting clothes means mending loose buttons, sewing popped seams, and washing garments gently instead of discarding them.\n                    </p>\n                </div>\n                <div class="p-3 rounded-xl bg-slate-900 border border-slate-700/80">\n                    <span class="text-xs font-bold text-emerald-400 block mb-1">🤝 Supporting Handloom Communities</span>\n                    <p class="text-xs text-slate-300">\n                        Visiting local weavers, khadi bhandars, and tailors connects us with the living hands that dress our nation. Choosing authentic Indian handlooms sustains millions of rural families and protects ancient cultural heritage.\n                    </p>\n                </div>\n            </div>\n            <p>Wear natural, mend with care, upcycle with creativity, and wear India\'s handcrafted pride with honour!</p>\n        ', 'spoken_text': 'We conclude our journey into clothing with a heartfelt appreciation for every thread! The next time you put on your school uniform or festive kurta, remember the long chain of nature and human hands behind it: from the sun and soil that nurtured the cotton plant, to the farmer harvesting fluffy bolls, the spinner twisting fibres on a charkha, the weaver guiding shuttles across the loom, and the tailor stitching seams with needle and thread! A single shirt holds twenty kilometres of yarn and days of human devotion. Treat your clothes with care, mend loose buttons with running stitches, upcycle old fabrics, and celebrate the timeless beauty of Indian handlooms!', 'lecture_script': 'Synthesizes the entire textile supply chain from agriculture to spinning, handloom weaving, stitching, and recycling, encouraging ethical stewardship and support for artisan communities.', 'checkpoints': [{'question': 'Approximately how many total kilometres of spun thread can be interlaced inside a single cotton shirt?', 'options': ['Over 15 to 20 kilometres of thread', 'Only 5 centimetres', 'Exactly 1 metre', '1,000 kilometres'], 'correct': 0, 'explanation': 'Because fine yarns are packed at 50 to 100 threads per inch across both warp and weft, an average cotton shirt contains roughly 20 km of spun fiber!', 'study_insight': 'National Handloom Day is celebrated every year in India on August 7 to commemorate the historic Swadeshi Movement launched in 1905.'}, {'question': 'What is the most respectful and sustainable way to care for our personal wardrobe?', 'options': ['Mending loose seams and buttons, washing gently, and upcycling old clothes instead of throwing them away', 'Throwing clothes into garbage bins after wearing them twice', 'Burning clothes whenever they get a small stain', 'Only buying clothes made of plastic foil'], 'correct': 0, 'explanation': 'Proper garment care, timely mending with needle and thread, and creative upcycling preserve natural resources and reduce landfill pollution.', 'study_insight': 'Visiting a local tailor or khadi handloom cooperative gives students direct firsthand understanding of the skill, patience, and dignity of artisan labour.'}]}]

QUIZ_QUESTIONS = [{'id': 1, 'question': 'Which natural creature constructs intricate pouch-shaped hanging nests by interlacing grass ribbons over and under each other?', 'options': ['The Indian robin', 'The male baya weaver (weaverbird)', 'The house sparrow', 'The common kingfisher'], 'answer': 1, 'explanation': 'The male baya weaver bird selects sturdy blade strips of grass or palm fronds and expertly weaves them in an over-under pattern to form a secure hanging pouch nest with a downward entrance tube.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Nature's Master Architect:</strong></p>\n                <p class='text-slate-300'>The male baya weaver (<em>Ploceus philippinus</em>) harvests flexible green leaves and ties loops around tree twigs. By weaving crosswise strips over and under lengthwise ribbons, it constructs a durable nesting chamber that sways safely away from predators.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (The male baya weaver)</p>\n            </div>\n        "}, {'id': 2, 'question': 'What are the two intersecting sets of threads in fabric weaving called?', 'options': ['Stamens and pistils', 'Warp (tana) and weft (bana)', 'Ribbons and shoelaces', 'Stems and roots'], 'answer': 1, 'explanation': 'In weaving, the stationary vertical threads held under tension on a loom are called the warp (tana in Hindi), and the horizontal thread interlaced back and forth across them is called the weft (bana in Hindi).', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Loom Geometry & Terminology:</strong></p>\n                <p class='text-slate-300'>Weaving is the orthogonal interlacing of two thread families: the <strong>warp</strong> (longitudinal lengthwise threads) and the <strong>weft</strong> (transverse crosswise threads carried by a shuttle).</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Warp (tana) and weft (bana))</p>\n            </div>\n        "}, {'id': 3, 'question': 'How long has the tradition of handloom weaving flourished across the Indian subcontinent?', 'options': ['Around 50 years', 'Over 4,000 years, dating back to the Indus Valley Civilization', 'Since only the 1990s', 'Just 200 years'], 'answer': 1, 'explanation': 'Archaeological discoveries in Mohenjo-daro and Harappa prove that cotton cultivation, spinning with clay spindles, and handloom weaving have thrived in India for over 4,000 years.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Ancient Indian Textile Heritage:</strong></p>\n                <p class='text-slate-300'>Textile fragments dyed with madder roots recovered from Indus Valley excavations prove that Indian weavers mastered sophisticated weaving techniques and mordant dyeing more than four millennia ago.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Over 4,000 years, dating back to the Indus Valley Civilization)</p>\n            </div>\n        "}, {'id': 4, 'question': 'Which luxurious Indian weave from Tamil Nadu is renowned for pure mulberry silk, heavy gold zari threads, and contrasting temple borders?', 'options': ['Kanjeevaram (Kanchipuram)', 'Pashmina', 'Chikankari', 'Bandhani'], 'answer': 0, 'explanation': 'Kanjeevaram sarees from Tamil Nadu are handwoven from three-ply mulberry silk and pure metallic zari (gold/silver wrapped silk thread), celebrated for intricate temple motifs and interlocking borders.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Kanchipuram Silk Craft:</strong></p>\n                <p class='text-slate-300'>Kanjeevaram weavers use the <em>Korvai</em> technique where the body and border are woven separately and locked together with remarkable tensile strength, often adorned with woven golden peacock and lotus patterns.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Kanjeevaram)</p>\n            </div>\n        "}, {'id': 5, 'question': 'What is authentic Kashmiri Pashmina wool harvested from?', 'options': ['The underbelly down-fleece of high-altitude Changthangi goats', 'Synthetic polyester plastic fibres', 'Coarse camel bristles', 'Domestic duck feathers'], 'answer': 0, 'explanation': 'Pashmina is the ultra-fine winter undercoat combed from Changthangi (Capra hircus) goats living at freezing altitudes above 4,000 metres in Ladakh and Kashmir.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Pashmina Fleece Origin:</strong></p>\n                <p class='text-slate-300'>Changthangi goats survive winter temperatures down to -40 °C by growing an ultra-soft undercoat beneath their coarse guard hair. The combed fibres measure just 12 to 15 microns in diameter—several times finer than a human hair.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (The underbelly down-fleece of high-altitude Changthangi goats)</p>\n            </div>\n        "}, {'id': 6, 'question': 'What distinctive dyeing technique gives Ikat fabrics from Odisha and Gujarat their soft, feathered geometric edges?', 'options': ['Tie-dyeing the yarn bundles with precision resistance bindings BEFORE weaving', 'Painting directly onto finished garments with oil paints', 'Dipping completed clothes into bleach buckets', 'Spraying chemical ink through stencils'], 'answer': 0, 'explanation': "In Ikat (such as Odisha's Bandha or Gujarat's Patola), weavers bundle warp and/or weft yarns and tie them with water-resistant ties before dyeing, aligning dyed dots on the loom into intricate feathered patterns.", 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Resist-Dye Precision in Ikat:</strong></p>\n                <p class='text-slate-300'>Because the calculation and binding occur on bare yarn bundles before a single shuttle is thrown, the slight shift of thread tension on the loom produces the iconic feathered or blurred edge prized in world textiles.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Tie-dyeing yarn bundles with precision bindings BEFORE weaving)</p>\n            </div>\n        "}, {'id': 7, 'question': 'Why does twisting cotton fibres during spinning turn a weak cloud of fluff into a strong, continuous thread?', 'options': ['It glues the fibres with synthetic liquid rubber', 'Twisting presses overlapping fibres against each other, creating interlocking surface friction', 'It melts the cellulose into glass', 'It turns the cotton into metallic wire'], 'answer': 1, 'explanation': 'When short fibres are drawn parallel and given a spiral twist, lateral pressure causes their microscopic ridges to interlock, generating enough surface friction to resist tension without breaking.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Physics of Spinning:</strong></p>\n                <p class='text-slate-300'>Raw cotton fibres are only 2 to 3 cm long. Pulling and twisting them (using a spindle or wheel) converts tensile pull along the thread into compressive inward clamping force, holding the strand together purely through friction.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Twisting creates interlocking surface friction)</p>\n            </div>\n        "}, {'id': 8, 'question': 'What traditional Indian handheld tool consists of a slender metal rod with a small whorl weight used for manual spinning?', 'options': ['Takli (drop spindle)', 'Chisel', 'Hacksaw', 'Weaving shuttle'], 'answer': 0, 'explanation': 'A takli is a simple handheld spindle consisting of a weighted disc and a thin shaft, spun between the fingers to draw and twist fibre slivers into yarn.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Ancient Takli:</strong></p>\n                <p class='text-slate-300'>The takli is one of humanity's earliest spinning tools. The spinner twirls the spindle with one hand while drawing out raw cotton fibres with the other; inertia from the spinning whorl twists the thread continuously.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Takli (drop spindle))</p>\n            </div>\n        "}, {'id': 9, 'question': "Why did Mahatma Gandhi promote the charkha (spinning wheel) and khadi during India's freedom struggle?", 'options': ['To promote reliance on imported British factory textiles', 'As a powerful symbol of self-reliance (atmanirbhar), village empowerment, and swadeshi economic freedom', 'Because machines were completely banned by law', 'To make spinning mandatory for sports events'], 'answer': 1, 'explanation': 'Mahatma Gandhi championed khadi (homespun and handwoven cotton cloth) produced on village charkhas to break foreign economic dependence, revive rural livelihoods, and unite Indians under the ideal of self-reliance.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Khadi and Swadeshi:</strong></p>\n                <p class='text-slate-300'>Gandhi realized that true independence required economic freedom for rural millions. By spinning daily on the charkha, people produced their own cloth, boycotted imported mill-made cloth, and dignified manual labour.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Symbol of self-reliance, village empowerment, and swadeshi freedom)</p>\n            </div>\n        "}, {'id': 10, 'question': 'In classroom Activity 1 (Paper-Strip Weaving), what happens if you place all weft strips strictly over the warp strips without alternating?', 'options': ['It forms a tough, rigid fabric', 'The strips do not interlock and slide completely apart when lifted', 'The paper turns into transparent plastic', 'The paper strips glue themselves together'], 'answer': 1, 'explanation': "Without the alternating 'over-under, under-over' pattern, there is no physical entrapment or friction between perpendicular strips, meaning the structure falls apart immediately.", 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Principle of Interlacing:</strong></p>\n                <p class='text-slate-300'>Weaving requires every successive weft thread to alternate its path relative to its neighbor (Row 1: over-under; Row 2: under-over). This alternation traps each thread between its neighbors, creating mechanical coherence.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (The strips do not interlock and slide completely apart)</p>\n            </div>\n        "}, {'id': 11, 'question': 'Which of the following fibres is derived from a plant stalk or stem rather than a seed pod?', 'options': ['Cotton', 'Jute and Flax (Linen)', 'Wool', 'Silk'], 'answer': 1, 'explanation': 'Jute and flax are bast fibres harvested from the phloem tissues of plant stems through retting (soaking in water), whereas cotton grows as seed hairs inside a pod.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Plant Stem vs Seed Pod Fibres:</strong></p>\n                <p class='text-slate-300'>Cotton fibres are protective cellulose hairs surrounding cotton seeds. In contrast, jute, flax (linen), and hemp are harvested by submerging bundles of plant stems in water to loosen the long bast fibres from the woody core.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Jute and Flax (Linen))</p>\n            </div>\n        "}, {'id': 12, 'question': 'What is the primary chemical building block of natural plant fibres such as cotton and linen?', 'options': ['Petroleum hydrocarbons', 'Cellulose (natural plant polymer)', 'Keratin protein', 'Calcium carbonate'], 'answer': 1, 'explanation': 'Plant fibres are composed of cellulose, a natural polysaccharide polymer formed by chains of glucose molecules synthesized by plants.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Chemical Composition of Fibres:</strong></p>\n                <p class='text-slate-300'>Cotton, linen, jute, and bamboo consist of over 85–95% cellulose. Animal fibres (wool and silk) are made of proteins (keratin and fibroin/sericin), while synthetic fibres are petroleum polymers.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Cellulose (natural plant polymer))</p>\n            </div>\n        "}, {'id': 13, 'question': 'What are the four chronological stages in the life cycle of the silkworm (Bombyx mori)?', 'options': ['Egg -> Adult moth -> Cocoon -> Caterpillar', 'Egg -> Larva (caterpillar) -> Pupa (inside cocoon) -> Imago (adult silk moth)', 'Pupa -> Egg -> Cocoon -> Caterpillar', 'Larva -> Egg -> Adult moth -> Pupa'], 'answer': 1, 'explanation': 'The silk moth undergoes complete metamorphosis: tiny eggs hatch into voracious caterpillars feeding on mulberry leaves, which spin protective silk cocoons to pupate before emerging as adult moths.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Silkworm Metamorphosis:</strong></p>\n                <p class='text-slate-300'>1. Egg: Laid by female moth.<br>2. Larva/Caterpillar: Feeds on fresh mulberry leaves for 4 to 6 weeks.<br>3. Pupa: Inside the silk cocoon spun by salivary glands.<br>4. Adult Silk Moth: Emerges to reproduce.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Egg -> Larva -> Pupa -> Imago)</p>\n            </div>\n        "}, {'id': 14, 'question': 'How does a silkworm caterpillar spin its protective silk cocoon?', 'options': ['By secreting liquid fibroin protein from modified salivary glands in continuous figure-8 head motions', 'By collecting spider webs from garden branches', 'By chewing dry twigs into paste', 'By rolling itself in dry mulberry leaves'], 'answer': 0, 'explanation': 'The caterpillar expels two strands of liquid fibroin coated with gummy sericin from its spinneret, swinging its head in figure-8 motions. Upon air contact, the liquid solidifies into a single unbroken filament up to 1,000 metres long.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Silk Spinning Mechanism:</strong></p>\n                <p class='text-slate-300'>Specialized silk glands produce fibroin protein coated with sticky sericin glue. Moving its head 300,000 times in continuous figure-8 patterns over 3 to 4 days, the caterpillar creates a warm, resilient cocoon.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Secreting liquid fibroin protein in figure-8 head motions)</p>\n            </div>\n        "}, {'id': 15, 'question': 'What raw material is used to manufacture fully synthetic fibres like polyester, nylon, and acrylic?', 'options': ['Petroleum crude oil and petrochemical derivatives', 'Crushed rock salt', 'Cow milk whey', 'Pure river rainwater'], 'answer': 0, 'explanation': 'Synthetic fibres are non-natural polymers synthesized from petrochemical feedstocks derived from refined crude oil and natural gas.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Petrochemical Origin of Synthetics:</strong></p>\n                <p class='text-slate-300'>Nylon (polyamide) and polyester (polyethylene terephthalate) are produced through industrial chemical synthesis using hydrocarbon molecules extracted from petroleum.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Petroleum crude oil and petrochemical derivatives)</p>\n            </div>\n        "}, {'id': 16, 'question': 'Why is wearing synthetic clothing (such as polyester or nylon) dangerous around open kitchen flames or Diwali firecrackers?', 'options': ['Synthetic fabrics freeze solid when exposed to fire', 'Synthetic fabrics melt into hot, sticky molten plastic that adheres to human skin, causing severe deep burns', 'Synthetics cause sudden electrical explosions', 'They attract insects when near heat'], 'answer': 1, 'explanation': 'Unlike cotton which burns to harmless powdery ash, synthetic fibres melt at high temperatures into sticky molten plastic drops that weld to human skin, causing excruciating, deep thermal burns.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Thermal Hazard of Synthetics:</strong></p>\n                <p class='text-slate-300'>Natural cotton burns cleanly without melting, making it easy to remove if ignited. Synthetic polymers melt into blazing viscous liquid that cannot be wiped off without tearing the skin underneath. Always wear 100% cotton around flames.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Melts into hot, sticky molten plastic adhering to skin)</p>\n            </div>\n        "}, {'id': 17, 'question': "Which bird acts as nature's tailor by puncturing holes along leaf margins and stitching them together into a nesting cone?", 'options': ['The common tailorbird (Orthotomus sutorius)', 'The house crow', 'The blue rock pigeon', 'The great Indian bustard'], 'answer': 0, 'explanation': 'The tailorbird uses its sharp, needle-like beak to punch pairs of eyelet holes along the edges of broad leaves (like mango or fig leaves) and stitches them together using plant lint and spider silk.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Nature's Living Tailor:</strong></p>\n                <p class='text-slate-300'>The common tailorbird (<em>Orthotomus sutorius</em>) selects living leaves on a branch. Piercing tiny holes along the edges, it threads cotton fibres or spider silk through, forming tiny tangled knots on the outer side like rivets to create a cradle nest.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (The common tailorbird)</p>\n            </div>\n        "}, {'id': 18, 'question': "What keeps the tailorbird's thread from slipping out of the punctured leaf holes?", 'options': ['The bird glues them with superglue', 'The bird tangles and fluffs the thread ends on the outside into small knots resembling rivets', 'The leaves heal around the thread instantly', 'The bird holds them with its claws for three months'], 'answer': 1, 'explanation': 'The bird pulls the fibre through and pecks at the exposed ends so they unravel into little cottony balls or knots on the leaf exterior, acting like rivets or stops that prevent thread slippage.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Avian Rivet Mechanism:</strong></p>\n                <p class='text-slate-300'>By deliberately fraying the fibre ends on the outside of the leaf, the tailorbird forms a natural knot or stopper that anchors the stitch under tension, creating an enclosed leafy hammock for its eggs.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Tangles thread ends into small knots resembling rivets)</p>\n            </div>\n        "}, {'id': 19, 'question': 'Why are woollen clothes uniquely suited for cold winter months?', 'options': ['Wool fibres are solid glass cylinders that radiate electricity', 'Wool fibres possess natural crimps and curls that trap millions of dead-air pockets, creating a superb thermal insulator', 'Wool absorbs all sunlight and turns blue', 'Wool has no weight and floats in air'], 'answer': 1, 'explanation': 'The natural crimp and elasticity of sheep wool fibres create pockets of still, trapped air. Since stagnant air is a poor conductor of heat, it prevents body warmth from escaping into cold surroundings.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Thermal Insulation of Wool:</strong></p>\n                <p class='text-slate-300'>Air is one of the best natural thermal insulators if prevented from circulating. The wavy, scaly structure of wool fibres holds air stationary against the skin, maintaining core body temperature during chilly winters.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Crimps and curls trap dead-air pockets as thermal insulation)</p>\n            </div>\n        "}, {'id': 20, 'question': 'Which of these is a semi-synthetic fibre manufactured by chemically regenerating natural wood pulp cellulose?', 'options': ['Rayon (viscose)', 'Nylon 6,6', 'Pure mulberry silk', 'Polyester'], 'answer': 0, 'explanation': 'Rayon is classified as a regenerated cellulose fibre because it starts with natural plant wood pulp or bamboo, which is chemically dissolved and extruded into silky filament threads.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Regenerated Cellulose:</strong></p>\n                <p class='text-slate-300'>Unlike purely synthetic fibres derived from petroleum, rayon is manufactured from renewable wood cellulose. Because its chemical backbone remains cellulose, it breathes and absorbs moisture much like cotton.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Rayon (viscose))</p>\n            </div>\n        "}, {'id': 21, 'question': "What is the most fundamental hand-stitching technique, characterized by an even 'in-and-out' needle motion along a straight line?", 'options': ['Running stitch (kaccha tanka)', 'Cross stitch', 'Satin stitch', 'Blanket stitch'], 'answer': 0, 'explanation': 'The running stitch is the simplest and oldest hand-sewing stitch, created by passing the needle evenly up and down through the fabric at regular intervals.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Fundamental Running Stitch:</strong></p>\n                <p class='text-slate-300'>In Hindi termed <em>kaccha tanka</em>, the running stitch involves passing a threaded needle alternately over and under the cloth. When stitched with even tension and spacing, it creates flexible, durable seams and forms the basis of Kantha quilting.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Running stitch (kaccha tanka))</p>\n            </div>\n        "}, {'id': 22, 'question': 'In classroom Activity 7 and 8, what practical everyday item can students create by joining colourful textile scraps with running stitches?', 'options': ['A patchwork mat, coaster, or table runner', 'A steel cooking spoon', 'A glass windowpane', 'A clay flowerpot'], 'answer': 0, 'explanation': 'Students salvage unused fabric cuttings from local tailor shops and join them edge-to-edge using running stitches to create beautiful patchwork mats, coasters, and small tote bags.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Patchwork Craft (Activities 7 & 8):</strong></p>\n                <p class='text-slate-300'>Patchwork combines creativity and zero-waste discipline. By cutting leftover scraps into uniform geometric shapes (squares, triangles) and stitching them with running stitches, waste is converted into functional, durable home textiles.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (A patchwork mat, coaster, or table runner)</p>\n            </div>\n        "}, {'id': 23, 'question': 'Which historic city in Uttar Pradesh is globally famous for the exquisite, delicate white-on-white embroidery known as Chikankari?', 'options': ['Lucknow', 'Agra', 'Varanasi', 'Kanpur'], 'answer': 0, 'explanation': 'Lucknow is the heartland of Chikankari, a refined art form involving 32 distinct stitches embroidered onto lightweight, translucent fabrics like muslin, cotton, and georgette.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Lucknow Chikankari:</strong></p>\n                <p class='text-slate-300'>Patronized by the Nawabs of Awadh, Chikankari traditionally uses white untwisted cotton thread on sheer white cotton or muslin, celebrated for intricate floral creepers, paisleys, and airy jaali (net) work.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Lucknow)</p>\n            </div>\n        "}, {'id': 24, 'question': 'What is the famous shadow-work herringbone stitch in Chikankari called, which is worked on the reverse side of cloth to create an opaque silhouette on the front?', 'options': ['Bakhiya', 'Murri', 'Tepchi', 'Phanda'], 'answer': 0, 'explanation': 'Bakhiya is the signature shadow stitch of Chikankari: worked crisscross on the reverse side of sheer muslin, it leaves a delicate faint outline on the front with a softly shaded interior.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Bakhiya (Shadow Stitch):</strong></p>\n                <p class='text-slate-300'>By covering the back of the motif with dense herringbone stitches, light passing through translucent fabric shows a solid shadow surrounded by a crisp perimeter—a hallmark of authentic Lucknow craftsmanship.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Bakhiya)</p>\n            </div>\n        "}, {'id': 25, 'question': 'Which nomadic community in Rajasthan and Gujarat is renowned for embedding shimmering circular mirrors (aabhla) into vibrantly embroidered textiles?', 'options': ['Banjara (Lambani)', 'Inuit', 'Maasai', 'Bedouin'], 'answer': 0, 'explanation': 'The Banjara (Lambani) artisans craft breathtaking embroidered garments using chain stitches, cowrie shells, coins, and tiny circular glass mirrors (shisha or aabhla) bound tightly with buttonhole stitches.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Banjara Mirror-Work Tradition:</strong></p>\n                <p class='text-slate-300'>Banjara embroidery uses brilliant red, indigo, and yellow fabrics. Small reflective mirrors are encased within secure circular stitches to ward off evil spirits, reflect the fierce desert sun, and display striking tribal identity.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Banjara (Lambani))</p>\n            </div>\n        "}, {'id': 26, 'question': 'How are traditional Kantha quilts in West Bengal, Odisha, and Tripura created from worn-out sarees and dhotis?', 'options': ['By layering old cotton cloths together and binding them with thousands of tiny, rippling running stitches', 'By melting the old clothes in acid', 'By gluing them with rubber cement', 'By painting them with oil varnish'], 'answer': 0, 'explanation': 'Kantha is a centuries-old recycling craft where women stack four to seven layers of soft, worn cotton sarees and dhotis, sewing them together with dense rows of running stitches using threads pulled from the saree borders.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Art and Soul of Kantha:</strong></p>\n                <p class='text-slate-300'>Nothing was wasted: thread was carefully unraveled from old garment borders to stitch layered quilts (nakshi kantha). The thousands of running stitches give the quilt a warm, textured, rippling quilted feel and depict folk motifs of fish, trees, and lotus blooms.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Layering old cloths with thousands of rippling running stitches)</p>\n            </div>\n        "}, {'id': 27, 'question': 'Which royal Rajasthani applique craft uses gold and silver metallic ribbons cut into diamond and petal shapes to embellish festive attire?', 'options': ['Gota Patti', 'Kashida', 'Toda', 'Khneng'], 'answer': 0, 'explanation': 'Gota Patti is an applique embroidery originating in Rajasthan (Jaipur, Bikaner) where narrow woven gold and silver ribbons (gota) are shaped into leaf, petal, and bird motifs and hand-stitched onto royal silks and bandhanis.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Gota Patti Applique:</strong></p>\n                <p class='text-slate-300'>Artisans fold and trim the metallic ribbon into delicate teardrops (patti) and diamonds, stitching each petal down with fine thread to form flowers, peacocks, and geometrical lattices that shimmer in the sunlight.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Gota Patti)</p>\n            </div>\n        "}, {'id': 28, 'question': 'What is the primary aesthetic and practical benefit of the rippling Kantha running-stitch layers?', 'options': ['It traps air between the soft layers for light warmth, softens with each wash, and transforms fragile old cloths into a strong composite fabric', 'It turns the quilt into waterproof rubber', 'It makes the fabric heavy like concrete', 'It bleaches the fabric completely white'], 'answer': 0, 'explanation': 'The dense grid of running stitches anchors multiple thin, soft layers into a cohesive composite textile. The tiny ripples trap warmth, and the repeated washing softens the fabric while preserving incredible strength.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Textile Engineering of Kantha:</strong></p>\n                <p class='text-slate-300'>A single worn saree is weak and tearable. By quilting 4 to 6 worn layers with thousands of micro-stitches, the tension distributes across millions of contact points, giving birth to a breathable, cozy baby blanket or winter quilt.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Traps air for warmth, softens with washing, and creates a strong composite)</p>\n            </div>\n        "}, {'id': 29, 'question': 'In Banjara mirror work, why are mirrors held in place with thread rather than glue?', 'options': ['Interlocking buttonhole and chain stitches wrap firmly around the mirror rim, ensuring mirrors never drop off during active desert movement and washing', 'Glue was completely unknown to mankind', 'Thread makes the mirror grow larger', 'Mirror edges become invisible with thread'], 'answer': 0, 'explanation': 'Traditional Banjara women engineered circular cage stitches that grip the bevelled edge of each mirror securely against the thick fabric, ensuring longevity through nomadic travels and strenuous celebrations.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Mechanical Fastening in Textiles:</strong></p>\n                <p class='text-slate-300'>Glue dissolves in water and turns brittle under desert heat. By building a structural web of interlocking foundation stitches and buttonhole knots over the perimeter, the mirror is permanently trapped against the cloth.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Interlocking stitches wrap firmly around the mirror rim)</p>\n            </div>\n        "}, {'id': 30, 'question': 'Why is Chikankari traditionally executed on sheer, breathable fabrics like mulmul (fine muslin)?', 'options': ['Muslin provides a translucent canvas where the shadow stitches on the reverse side shine through delicately while offering sublime comfort in hot Awadh summers', 'Thick canvas is impossible to cut with scissors', 'Muslin glows in the dark at night', 'Muslin repels all rain completely'], 'answer': 0, 'explanation': "Awadh's warm climate required breezy, lightweight cottons. Sheer mulmul allowed the cooling comfort of pure cotton while highlighting the subtle interplay of light through delicate white embroidery.", 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Canvas of Awadh:</strong></p>\n                <p class='text-slate-300'>The extreme fineness of Dacca and Lucknow muslin made it the perfect medium for white-on-white needlework. The contrast between opaque thread stitches and translucent base fabric creates an ethereal, royal texture.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Translucent canvas showcases shadow stitches while offering cool comfort)</p>\n            </div>\n        "}, {'id': 31, 'question': "What is Punjab's iconic folk embroidery called, which literally translates to 'flower work' and is stitched with bright silk floss (pat) from the reverse side of handspun khaddar?", 'options': ['Phulkari', 'Kashida', 'Toda', 'Kantha'], 'answer': 0, 'explanation': "Phulkari (literally 'flower work') is the traditional embroidery of Punjab, created using untwisted silk floss (pat) worked in long and short darning stitches from the reverse side of coarse khaddar cotton.", 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Punjab's Floral Heritage:</strong></p>\n                <p class='text-slate-300'>Mothers and grandmothers in Punjab embroidered Phulkari shawls for brides. When the entire surface is covered so densely with silk floss that no base cloth is visible, it is called a <em>Bagh</em> (meaning 'garden').</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Phulkari)</p>\n            </div>\n        "}, {'id': 32, 'question': 'Which indigenous pastoral community of the Nilgiri Hills in Tamil Nadu embroiders striking red-and-black geometric patterns on white cotton shawls (Poothkuli)?', 'options': ['The Toda tribe', 'The Santhal tribe', 'The Gond tribe', 'The Bhil tribe'], 'answer': 0, 'explanation': 'The Toda people of the Nilgiris craft Poothkuli shawls featuring bold red and black geometric bands inspired by buffalo horns, butterflies, and stars, counted thread by thread to resemble woven cloth.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Toda Pukhoor Embroidery:</strong></p>\n                <p class='text-slate-300'>Toda women use a single needle and thick unspun wool/cotton thread, counting the warp and weft threads on unbleached white fabric without drawing any outlines. Sacred buffalo motifs honour their pastoral way of life.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (The Toda tribe)</p>\n            </div>\n        "}, {'id': 33, 'question': 'What natural motifs are famously depicted in Kashmiri Kashida embroidery on woollen pherans and shawls?', 'options': ['Chinar leaves, apple blossoms, almonds (badam/paisley), and nightingales (bulbul)', 'Automobiles and skyscrapers', 'Desert camels and cacti', 'Ocean sharks and starfish'], 'answer': 0, 'explanation': "Kashida draws direct inspiration from the paradise of Kashmir's valleys: chinar tree leaves, pine cones, saffron flowers, apple blossoms, and singing bulbuls stitched with fine single-strand thread.", 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Kashmiri Kashida Motifs:</strong></p>\n                <p class='text-slate-300'>Using chain stitch (Aari) or satin stitch with vivid jewel tones, Kashida artists reflect Kashmir's seasonal changes—from green spring blossoms to fiery autumn maple-like chinar leaves.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Chinar leaves, apple blossoms, almonds, and nightingales)</p>\n            </div>\n        "}, {'id': 34, 'question': 'Which rare fish-bone motif embroidery is practiced by Khasi women in Mustoh village, Meghalaya, using black thread on handspun Eri peace silk?', 'options': ['Khneng', 'Zardozi', 'Bandhani', 'Chamba Rumal'], 'answer': 0, 'explanation': 'Khneng is an endangered embroidery tradition from Mustoh village in Meghalaya, where artisans meticulously stitch fish-bone patterns along the border of Eri silk wrap-around skirts (Jainsem).', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Unique Khneng of Meghalaya:</strong></p>\n                <p class='text-slate-300'>Khneng mimics the spine of a local river fish. It is embroidered onto handspun Eri silk—known as 'peace silk' because the moth emerges naturally from the open cocoon without boiling the pupa.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Khneng)</p>\n            </div>\n        "}, {'id': 35, 'question': 'In traditional Indian households, what is the sustainable life cycle of a cotton textile garment?', 'options': ['Brand new clothes -> Younger sibling hand-me-down -> Godhari quilt / rag doll -> Cleaning mop -> Composted in garden soil', 'Worn once -> Thrown into a plastic landfill', 'Burned immediately after two washes', 'Buried in metal boxes underground'], 'answer': 0, 'explanation': 'Indian culture practices true circularity: good clothes pass to younger siblings; worn garments are stitched into Godhari quilts, baby wraps, or kitchen mats; remnants become mops; and 100% cotton decomposes naturally into compost.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Zero-Waste Indian Circular Economy:</strong></p>\n                <p class='text-slate-300'>Indian homes maximize every thread's lifetime. From festive celebration to soft cradle cloth, quilt padding, dusters, and organic soil enrichment, zero fabric reaches municipal landfills.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (New clothes -> Hand-me-down -> Quilt -> Mop -> Compost)</p>\n            </div>\n        "}, {'id': 36, 'question': 'In a laboratory flame burn test, what distinct odor and residue does pure cotton produce?', 'options': ['Smells like burning paper and leaves light, fluffy grey-black ash', 'Smells like sweet candy and turns into yellow liquid', 'Smells like burning hair and forms a hard rock', 'Produces no smoke and turns into green sparks'], 'answer': 0, 'explanation': 'Because cotton is composed of pure plant cellulose (the exact same chemical substance as wood pulp paper), it burns with a steady yellow flame, smells like burning paper or dry leaves, and leaves powdery grey ash.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Cotton Burn Test Signature:</strong></p>\n                <p class='text-slate-300'>- Chemical: Cellulose polymer.<br>- Flame: Ignites quickly, steady glowing ember.<br>- Odour: Burning paper/wood.<br>- Residue: Soft, light grey-white ash that crumbles easily between fingers.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: A (Smells like burning paper and leaves fluffy grey ash)</p>\n            </div>\n        "}, {'id': 37, 'question': 'In a flame burn test, what characteristic smell identifies natural animal fibres such as wool and silk?', 'options': ['A sharp chemical plastic odor', 'A strong smell of burning hair or feathers (due to sulfur-bearing proteins)', 'The scent of fresh cut grass', 'A citrus lemon smell'], 'answer': 1, 'explanation': 'Wool and silk are animal proteins (keratin and fibroin) containing sulfur amino acids. When burned, they emit a distinct singed hair or burning feather smell and leave a dark, crushable irregular bead.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Protein Fibre Burn Test:</strong></p>\n                <p class='text-slate-300'>- Chemical: Keratin/Fibroin protein chains.<br>- Flame: Burns slowly, self-extinguishes away from flame.<br>- Odour: Burning hair or roasted feathers.<br>- Residue: Black, hollow, brittle bead that easily crumbles into powder.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Smell of burning hair or feathers)</p>\n            </div>\n        "}, {'id': 38, 'question': 'What happens when synthetic polyester or nylon is touched by a flame during a burn test?', 'options': ['It turns instantly into clean drinking water', 'It shrinks away from the heat, melts into a dark liquid, emits black chemical smoke, and hardens into an uncrushable plastic bead', 'It blows up like a party cracker', 'It freezes into cold ice cubes'], 'answer': 1, 'explanation': 'Synthetic petrochemical fibres are plastics. When heated, they shrink, melt, produce pungent chemical smoke, and cool down into a hard, rigid plastic bead that cannot be crushed by finger pressure.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>Synthetic Polymer Burn Test:</strong></p>\n                <p class='text-slate-300'>- Chemical: Petrochemical polymer chains.<br>- Flame: Melts and drips sticky black droplets with acidic smoke.<br>- Odour: Sweet chemical / celery-like pungent plastic odor.<br>- Residue: Hard, round, shiny uncrushable plastic bead.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Shrinks, melts, emits black smoke, and hardens into an uncrushable bead)</p>\n            </div>\n        "}, {'id': 39, 'question': 'Approximately how many kilometres of continuous thread are woven together to craft an ordinary adult cotton shirt?', 'options': ['Just 10 metres', 'About 20 to 25 kilometres of fine thread', 'Exactly 5 centimetres', 'Over 1,000,000 kilometres'], 'answer': 1, 'explanation': 'A typical cotton shirt contains between 20 to 25 kilometres of spun yarn, representing thousands of farmer hours, spinning rotations, and loom crossings.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Scale of Textile Creation:</strong></p>\n                <p class='text-slate-300'>If all the warp and weft yarns in your school shirt or dress were unraveled and tied end-to-end, they would stretch across 20 to 25 kilometres—connecting two nearby towns! Every garment embodies enormous human effort and natural resources.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (About 20 to 25 kilometres of fine thread)</p>\n            </div>\n        "}, {'id': 40, 'question': 'What core attitude does NCERT Chapter 8 inspire students to adopt toward our clothes and the artisans who create them?', 'options': ['Discard clothes after one wear to buy fast fashion', 'Value garments as precious treasures of nature and human artistry, practice mending and upcycling, and honor our handloom artisans', 'Replace all handloom clothes with single-use plastic wraps', 'Never wash any clothes to save soap'], 'answer': 1, 'explanation': 'Understanding how threads are spun, woven, and embroidered teaches us deep respect for natural fibres, circular recycling traditions, and the gifted master weavers and tailors of India.', 'solution_html': "\n            <div class='space-y-2 text-xs'>\n                <p><strong>The Textile Guardian Ethos:</strong></p>\n                <p class='text-slate-300'>Clothes are not disposable garbage; they are crafted from nature's gifts and human genius. By learning basic stitching, caring for our clothes, mending loose buttons, and supporting Indian handlooms, students become responsible Textile Guardians.</p>\n                <p class='text-emerald-400 font-bold'>Correct Option: B (Value garments as precious treasures, practice mending and upcycling, and honor artisans)</p>\n            </div>\n        "}]
